import{_ as s,o as a,c as t,a2 as o}from"./chunks/framework.Wk4ah3nE.js";const g=JSON.parse('{"title":"How scaling decisions are made","description":"The full decision path Proxmox VM Autoscale takes each cycle — gates, thresholds, step sizes, limits and per-resource cooldowns.","frontmatter":{"title":"How scaling decisions are made","description":"The full decision path Proxmox VM Autoscale takes each cycle — gates, thresholds, step sizes, limits and per-resource cooldowns.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/how-it-works.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/how-it-works.html"}],["meta",{"property":"og:title","content":"How scaling decisions are made"}],["meta",{"property":"og:description","content":"The full decision path Proxmox VM Autoscale takes each cycle — gates, thresholds, step sizes, limits and per-resource cooldowns."}]]},"headers":[],"relativePath":"guide/how-it-works.md","filePath":"guide/how-it-works.md","lastUpdated":null}'),n={name:"guide/how-it-works.md"};function i(r,e,l,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="how-scaling-decisions-are-made" tabindex="-1">How scaling decisions are made <a class="header-anchor" href="#how-scaling-decisions-are-made" aria-label="Permalink to &quot;How scaling decisions are made&quot;">​</a></h1><p>Every decision this service makes comes from one pass of the logic below. There is no state carried between cycles other than the cooldown timers.</p><h2 id="the-cycle" tabindex="-1">The cycle <a class="header-anchor" href="#the-cycle" aria-label="Permalink to &quot;The cycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>every check_interval seconds</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└─ for each host in proxmox_hosts</span></span>
<span class="line"><span>   └─ for each VM in virtual_machines where proxmox_host == host.name</span></span>
<span class="line"><span>      │                                    and scaling_enabled == true</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ├─ open SSH connection to the host</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ├─ GATE 1  is the guest running?          qm status &lt;id&gt; --verbose</span></span>
<span class="line"><span>      │          └─ no  → skip this VM</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ├─ GATE 2  does the host have headroom?   pvesh get /nodes/&lt;n&gt;/status</span></span>
<span class="line"><span>      │          └─ no  → skip this VM, log a warning</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ├─ read CPU% and RAM% for the guest       pvesh get /cluster/resources</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ├─ if cpu_scaling:  evaluate CPU thresholds → maybe scale</span></span>
<span class="line"><span>      ├─ if ram_scaling:  evaluate RAM thresholds → maybe scale</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      └─ close SSH connection</span></span></code></pre></div><p>Both gates are checked <strong>before</strong> any usage is read, and both are hard stops for that VM in that cycle. A VM that is powered off costs one <code>qm status</code> call and nothing else.</p><h2 id="gate-1-—-is-the-guest-running" tabindex="-1">Gate 1 — is the guest running? <a class="header-anchor" href="#gate-1-—-is-the-guest-running" aria-label="Permalink to &quot;Gate 1 — is the guest running?&quot;">​</a></h2><p><code>qm status &lt;vmid&gt; --verbose</code> is parsed for the literal string <code>status: running</code>. Retried up to three times with an increasing delay, because a node under load occasionally times out. If all three attempts fail, the VM is treated as not running and skipped.</p><h2 id="gate-2-—-does-the-host-have-headroom" tabindex="-1">Gate 2 — does the host have headroom? <a class="header-anchor" href="#gate-2-—-does-the-host-have-headroom" aria-label="Permalink to &quot;Gate 2 — does the host have headroom?&quot;">​</a></h2><p>Read from <code>pvesh get /nodes/$(hostname)/status --output-format json</code>:</p><ul><li><strong>CPU</strong> — the node&#39;s <code>cpu</code> field, a fraction, multiplied by 100.</li><li><strong>RAM</strong> — <code>memory.used / memory.total × 100</code>.</li></ul><div class="info custom-block"><p class="custom-block-title">Why <code>used</code> and not <code>total - free</code></p><p><code>used</code> excludes reclaimable buff/cache and matches what the Proxmox web UI shows. An earlier version computed availability from <code>free + cached</code>, which made a node with a warm page cache look 90% full when it was really at 66%, silently suppressing all scaling. Fixed in <a href="/proxmox-vm-autoscale/reference/changelog.html">0.1.1</a>.</p></div><p>If either figure exceeds <code>host_limits.max_host_cpu_percent</code> or <code>max_host_ram_percent</code>, the whole VM is skipped — including scale <strong>down</strong>, which is arguably backwards, since shrinking a guest is exactly what you want on a saturated node. Worth knowing if your node sits near its ceiling.</p><h2 id="reading-guest-usage" tabindex="-1">Reading guest usage <a class="header-anchor" href="#reading-guest-usage" aria-label="Permalink to &quot;Reading guest usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pvesh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /cluster/resources</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;qemu/&lt;vmid&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;│&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print $6, $15, $16}&#39;</span></span></code></pre></div><p>The three fields are CPU percentage, maximum memory and used memory. CPU is taken from the leading percentage; RAM percentage is computed as used ÷ maximum, with MiB and GiB units normalised.</p><div class="warning custom-block"><p class="custom-block-title">This parsing is fragile</p><p>It depends on <code>pvesh</code>&#39;s human-readable table: on the box-drawing separator, on those exact column positions, and on <code>grep</code> matching. <code>grep &#39;qemu/101&#39;</code> also matches VMID <code>1010</code> and <code>1011</code>. If usage always reads as <code>0.0%</code> on your Proxmox version, this is almost certainly why — see <a href="/proxmox-vm-autoscale/reference/limitations.html#metric-parsing-is-format-sensitive">known limitations</a>.</p></div><p>When usage cannot be parsed the service logs a warning and uses <code>0.0</code>. Zero is below every sensible <code>low</code> threshold, so <strong>an unreadable metric looks identical to an idle guest</strong> and triggers a scale <em>down</em>. This is the mechanism behind several historical &quot;scaled down to minimum for no reason&quot; reports.</p><h2 id="the-thresholds" tabindex="-1">The thresholds <a class="header-anchor" href="#the-thresholds" aria-label="Permalink to &quot;The thresholds&quot;">​</a></h2><p>CPU and RAM are evaluated independently, each against <code>scaling_thresholds</code>:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Action</th></tr></thead><tbody><tr><td><code>usage &gt; high</code></td><td>Scale that resource <strong>up</strong> one step</td></tr><tr><td><code>low ≤ usage ≤ high</code></td><td>Nothing — this is the dead band</td></tr><tr><td><code>usage &lt; low</code></td><td>Scale that resource <strong>down</strong> one step</td></tr></tbody></table><p>Comparisons are strict (<code>&gt;</code> and <code>&lt;</code>), so a value sitting exactly on a threshold does nothing.</p><div class="tip custom-block"><p class="custom-block-title">Keep the dead band wide</p><p>The gap between <code>low</code> and <code>high</code> is your only defence against oscillation. With <code>low: 60</code> and <code>high: 70</code>, a guest hovering near 65% will bounce up and down forever, each flap costing a <code>qm set</code>. The shipped defaults (20/80 for CPU, 25/85 for RAM) are wide for good reason.</p></div><p>CPU is always evaluated before RAM. If CPU scaling raises an exception the service logs it and still proceeds to RAM.</p><h2 id="step-sizes" tabindex="-1">Step sizes <a class="header-anchor" href="#step-sizes" aria-label="Permalink to &quot;Step sizes&quot;">​</a></h2><p>Steps are fixed and not configurable:</p><table tabindex="0"><thead><tr><th>Resource</th><th>Step</th></tr></thead><tbody><tr><td>CPU</td><td>1 core / 1 vCPU</td></tr><tr><td>RAM</td><td>512 MB</td></tr></tbody></table><p>One step per resource per cycle. Recovering from a large, sudden jump therefore takes several cycles: going from 2 to 8 cores needs six cycles, each separated by at least <code>scale_cooldown</code>.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><p>Steps are clamped by <code>scaling_limits</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">scaling_limits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  min_cores</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_cores</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  min_ram_mb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_ram_mb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16384</span></span></code></pre></div><p>At a boundary the corresponding direction becomes a no-op: <code>No CPU scaling required.</code> in the log, no notification, and — importantly — <strong>no cooldown consumed</strong>.</p><div class="danger custom-block"><p class="custom-block-title">These limits were ignored before the fix</p><p>Until recently the code looked these values up under names that do not exist in <code>config.yaml</code>, so every installation ran on the hardcoded defaults 1–8 cores and 512–16384 MB regardless of what you wrote. If you are upgrading from an older version, your configured limits are about to start applying for the first time — re-read them before you upgrade. See the <a href="/proxmox-vm-autoscale/reference/changelog.html">changelog</a>.</p></div><h2 id="cooldowns" tabindex="-1">Cooldowns <a class="header-anchor" href="#cooldowns" aria-label="Permalink to &quot;Cooldowns&quot;">​</a></h2><p><code>scale_cooldown</code> (default 300 s) is the minimum time between two scaling actions <strong>on the same resource of the same VM</strong>.</p><p>Three properties are worth stating precisely:</p><ol><li><strong>CPU and RAM have separate timers.</strong> A CPU change does not delay a RAM change. (They shared one timer before; that is what made RAM appear to stop scaling whenever CPU was active — <a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/issues/30" target="_blank" rel="noreferrer">issue #30</a>.)</li><li><strong>Only a real change starts the timer.</strong> Crossing a threshold while already at a limit changes nothing and rate-limits nothing.</li><li><strong>Timers live in memory.</strong> They survive between cycles, but a service restart clears them. After <code>systemctl restart</code>, the first cycle can scale immediately.</li></ol><p>The effective interval between two changes to the same resource is therefore <code>max(check_interval, scale_cooldown)</code> rounded up to a cycle boundary. Setting <code>scale_cooldown</code> below <code>check_interval</code> has no effect.</p><h2 id="applying-the-change" tabindex="-1">Applying the change <a class="header-anchor" href="#applying-the-change" aria-label="Permalink to &quot;Applying the change&quot;">​</a></h2><p>What actually reaches the hypervisor depends on the guest&#39;s hotplug state — the <a href="/proxmox-vm-autoscale/guide/hotplug.html">hotplug and NUMA</a> page covers this in full. Summarised:</p><table tabindex="0"><thead><tr><th>Guest state</th><th>CPU up</th><th>RAM change</th></tr></thead><tbody><tr><td>Running, hotplug + NUMA on</td><td><code>qm set -vcpus</code> (live), <code>-cores</code> if vCPUs are already at the core count</td><td><code>qm set -balloon</code> (live)</td></tr><tr><td>Running, hotplug on, NUMA off</td><td><code>-cores</code> + <code>-vcpus</code>, warning logged</td><td><code>qm set -memory</code>, needs reboot</td></tr><tr><td>Running, no hotplug</td><td><code>-cores</code> + <code>-vcpus</code>, warning logged</td><td><code>qm set -memory</code>, needs reboot</td></tr><tr><td>Stopped</td><td><code>-cores</code> + <code>-vcpus</code></td><td><code>qm set -memory</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">A logged success is not a confirmed change</p><p>The service logs <code>RAM balloon set to 4096 MB</code> after the command returns. It does not verify that the guest honoured it. A guest without a working balloon driver, or one whose kernel refuses a CPU hot-add, will report success in the log and change nothing. Check <code>qm config</code> and the guest itself when it matters.</p></div><h2 id="after-a-change" tabindex="-1">After a change <a class="header-anchor" href="#after-a-change" aria-label="Permalink to &quot;After a change&quot;">​</a></h2><ul><li>The action is logged at <code>INFO</code>.</li><li>A notification goes out via every configured channel, priority 7 for scale-up and 5 for scale-down (<a href="/proxmox-vm-autoscale/guide/notifications.html">notifications</a>).</li><li>If billing is enabled, the new spec is recorded with a timestamp (<a href="/proxmox-vm-autoscale/guide/billing.html">billing</a>).</li><li>The cooldown timer for that resource starts.</li></ul><p>Errors while processing a VM are caught per-VM: they are logged, sent as a priority-9 notification, and the loop moves on to the next VM. An unexpected error in the outer loop is logged at priority 10 and the service waits 60 seconds before retrying.</p>`,44)])])}const u=s(n,[["render",i]]);export{g as __pageData,u as default};
